layers = model.model.layers

def capture_routing(text):
    # selected expert ids at every layer -> (n_layers, n_tokens, K)
    with torch.no_grad():
        with model.trace(text):
            per_layer = nnsight.save([layers[l].mlp.gate.output[2]
                                      for l in range(N_LAYERS)])
    return torch.stack(per_layer)

captured = {}
for name, texts in GROUPS.items():
    captured[name] = torch.cat([capture_routing(t) for t in texts], dim=1)
    print(f"{name:9s} {captured[name].shape[1]:5d} tokens   "
          f"expert ids {tuple(captured[name].shape)}")

def js_divergence(p, q):
    m = 0.5 * (p + q)
    def kl(a, b):
        mask = a > 0
        return float((a[mask] * (a[mask] / b[mask]).log2()).sum())
    return 0.5 * kl(p, m) + 0.5 * kl(q, m)

def hist(idx_LTK, layer, cols=None):
    sel = idx_LTK[layer] if cols is None else idx_LTK[layer][cols]
    c = torch.bincount(sel.reshape(-1), minlength=E).float()
    return c / c.sum()

g = torch.Generator().manual_seed(0)

def split_half_control(name, layer, n_rep=20):
    idx = captured[name]
    T = idx.shape[1]
    vals = []
    for _ in range(n_rep):
        perm = torch.randperm(T, generator=g)
        a, b = perm[: T // 2], perm[T // 2 :]
        vals.append(js_divergence(hist(idx, layer, a), hist(idx, layer, b)))
    return sum(vals) / len(vals)

PAIRS = [("en_prose", "code"), ("en_prose", "fr"), ("en_prose", "de"), ("fr", "de")]

js_by_layer = {f"{a} vs {b}": [] for a, b in PAIRS}
ctrl_by_layer = []
for l in range(N_LAYERS):
    for a, b in PAIRS:
        js_by_layer[f"{a} vs {b}"].append(
            js_divergence(hist(captured[a], l), hist(captured[b], l)))
    ctrl_by_layer.append(
        sum(split_half_control(n, l) for n in GROUPS) / len(GROUPS))

print(f"{'comparison':22s} " + " ".join(f"L{l:<5d}" for l in (0, 4, 8, 12, 15)) + "   mean")
for k, v in js_by_layer.items():
    print(f"{k:22s} " + " ".join(f"{v[l]:.3f} " for l in (0, 4, 8, 12, 15))
          + f"  {sum(v)/len(v):.3f}")
print(f"{'split-half CONTROL':22s} "
      + " ".join(f"{ctrl_by_layer[l]:.3f} " for l in (0, 4, 8, 12, 15))
      + f"  {sum(ctrl_by_layer)/len(ctrl_by_layer):.3f}")

def usage_entropy(p):
    m = p > 0
    return float(-(p[m] * p[m].log2()).sum())

print(f"{'group':10s} " + " ".join(f"L{l:<5d}" for l in (0, 4, 8, 12, 15)) + "   effective #experts @L15")
for name in GROUPS:
    ents = [usage_entropy(hist(captured[name], l)) for l in range(N_LAYERS)]
    print(f"{name:10s} " + " ".join(f"{ents[l]:.3f} " for l in (0, 4, 8, 12, 15))
          + f"   {2 ** ents[-1]:.1f} of {E}")
